{
  "tickets": [
    {
      "id": "gen-211",
      "subject": "Can't figure out pharmacy substitution workflow",
      "body": "I'm trying to clear out-of-stock medication flags for a couple of patients and switch them to alternative drugs, but the system keeps looping me back to the original pharmacy message without letting me modify the script. Please tell me where the substitution button is hiding."
    },
    {
      "id": "gen-212",
      "subject": "Automated text reminders not sending",
      "body": "Patients are not receiving their text appointment reminders. I checked the settings under the scheduling tab and everything looks turned on, but nothing is going out. I even tried toggling the SMS switch off and back on yesterday, but it's still broken. Need this fixed ASAP."
    },
    {
      "id": "gen-213",
      "subject": "Sorry to bother you about our last invoice",
      "body": "I am so sorry to reach out about this, but I noticed we were billed twice for our monthly subscription fee on the latest statement. Could you please look into correcting the duplicate charge and refunding the extra amount to our account? Apologies for any inconvenience this causes."
    },
    {
      "id": "gen-214",
      "subject": "Routing abnormal lab results to covering providers",
      "body": "How do we route incoming lab results to a covering provider when the primary doctor is out of office? I checked the settings menu but couldn't find the forwarding rule. Please advise."
    },
    {
      "id": "gen-215",
      "subject": "Need help pulling claim denial reports",
      "body": "Where is the report for tracking recent insurance claim denials? Need to pull the data for our billing review meeting this afternoon."
    },
    {
      "id": "gen-216",
      "subject": "Locked out after password expiration policy change",
      "body": "Our front desk staff got locked out of their accounts this morning after the system forced a password reset. When they try to use the temporary link, it throws an error code 403. I tried resetting one manually from my admin profile, but it didn't send the new email either. This is completely halting our check-in process right now."
    },
    {
      "id": "gen-217",
      "subject": "Online booking letting patients pick wrong visit types",
      "body": "I am completely fed up with the patient portal settings. We keep having annual physicals booked with providers who only do consultations, even though I specifically unchecked those options in the portal configuration menu yesterday. Why is the system ignoring my rules and letting patients book whatever they want?"
    },
    {
      "id": "gen-218",
      "subject": "Prescription transmitted with incorrect medication strength",
      "body": "Dear Support Team, I am writing to report a serious transmission error regarding a prescription sent for patient J.D. earlier this morning. The medication was selected correctly in the chart, but the system populated an incorrect dosage strength upon transmission to the retail pharmacy. We have already contacted the pharmacist to halt dispensing, and we request your assistance in reviewing the transmission logs to understand how this substitution occurred."
    },
    {
      "id": "gen-219",
      "subject": "Urgent: Unresolved claim denials blocking patient accounts",
      "body": "I have several patients waiting in exam rooms and our billing queue is blocked by a batch of unresolved denials that won't let us update the secondary insurance. Could someone please look into this right away so we can get these claims processed and move forward with the day?"
    },
    {
      "id": "gen-220",
      "subject": "Confused about validation errors on custom intake form",
      "body": "I'm trying to set up a new digital intake questionnaire for our upcoming clinic rollout, but I keep hitting a roadblock with field validation errors on the medical history section. Every time I try to save the template, it flags a red error near the insurance upload block even though all the required toggles are checked. Could someone point out what I'm missing here?"
    }
  ]
}
